<script lang="ts">
 import {page} from '$app/state';
 let {model,t,lang='de',timezone='Europe/Berlin'}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string;lang?:string;timezone?:string}=$props();let lot=$state(''),parameter=$state('temperature'),method=$state(''),previousQuery=$state('');
 let measurements=$derived.by(()=>{const replaced=new Set(model.analyses.map(a=>a.supersedes).filter(Boolean));return model.analyses.filter(a=>a.lot_id===lot&&a.parameter===parameter&&a.quality==='measured'&&!replaced.has(a.id)).toSorted((a,b)=>Date.parse(a.measured_at)-Date.parse(b.measured_at));});
 let methods=$derived([...new Set(measurements.map(a=>a.method+' · '+a.unit))].sort((a,b)=>measurements.filter(v=>v.method+' · '+v.unit===b).length-measurements.filter(v=>v.method+' · '+v.unit===a).length));
 $effect(()=>{const requested=page.url.searchParams.get('lot')??'';if(requested&&requested!==previousQuery&&model.lots.some(l=>l.id===requested)){lot=requested;previousQuery=requested;}if(!lot)lot=model.fermentations.find(f=>f.status==='active')?.lot_id??model.lots[0]?.id??'';});
 $effect(()=>{if(!methods.includes(method))method=methods[0]??'';});
 let series=$derived(measurements.filter(a=>a.method+' · '+a.unit===method));
 let range=$derived.by(()=>{const vals=series.map(a=>Number(a.value)),min=Math.min(...vals),max=Math.max(...vals),padding=Math.max((max-min)*.15,.5);return {min:min-padding,max:max+padding};});
 let points=$derived(series.map(a=>({x:60+(Date.parse(a.measured_at)-Date.parse(series[0].measured_at))/(Date.parse(series.at(-1)!.measured_at)-Date.parse(series[0].measured_at)||1)*640,y:220-(Number(a.value)-range.min)/(range.max-range.min)*175,record:a})));
 const number=(value:number)=>new Intl.NumberFormat(lang,{maximumFractionDigits:2}).format(value),date=(value:string)=>new Intl.DateTimeFormat(lang,{dateStyle:'short',timeZone:timezone}).format(new Date(value));
</script>
<section class="card"><div class="chart-head"><h2>{t('measurementSeries')}</h2>{#if series.length}<span class="pill good">{series.length} {t('uxMeasurements')}</span>{/if}</div><div class="selectors"><label>{t('lot_id')}<select bind:value={lot}>{#each model.lots as l}<option value={l.id}>{l.code} · {l.name}</option>{/each}</select></label><label>{t('parameter')}<select bind:value={parameter}>{#each ['temperature','sugar','alcohol','acidity','ph','free_so2'] as p}<option value={p}>{p==='ph'?'pH':t(p)}</option>{/each}</select></label><label>{t('uxMethod')}<select bind:value={method} disabled={!methods.length}>{#each methods as m}<option value={m}>{m}</option>{/each}</select></label></div>{#if series.length}<div class="reading"><strong>{number(Number(series.at(-1)!.value))}<small>{series.at(-1)!.unit}</small></strong><span>{date(series.at(-1)!.measured_at)} · {series.at(-1)!.method}</span></div><svg viewBox="0 0 740 270" role="img" aria-label={t('measurementSeries')+' · '+t(parameter)}><title>{t('measurementSeries')} · {t(parameter)} · {method}</title><defs><linearGradient id="lab-area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#2b9a71" stop-opacity=".16"/><stop offset="100%" stop-color="#2b9a71" stop-opacity="0"/></linearGradient></defs>{#each [0,1,2,3,4] as i}{@const y=220-i*43.75}<line x1="60" y1={y} x2="700" y2={y} stroke="#e4ece6" stroke-dasharray="3 4"/><text x="48" y={y+4} text-anchor="end" font-size="11" fill="#60796b">{number(range.min+(range.max-range.min)*i/4)}</text>{/each}<polygon points={'60,220 '+points.map(p=>p.x+','+p.y).join(' ')+' '+points.at(-1)!.x+',220'} fill="url(#lab-area)"/><polyline points={points.map(p=>p.x+','+p.y).join(' ')} fill="none" stroke="#21865d" stroke-width="2.8"/>{#each points as p}<circle cx={p.x} cy={p.y} r="4.5" fill="white" stroke="#21865d" stroke-width="2"><title>{date(p.record.measured_at)}: {number(Number(p.record.value))} {p.record.unit} · {p.record.method}</title></circle>{/each}<text x="60" y="250" font-size="11" fill="#60796b">{date(series[0].measured_at)}</text><text x="700" y="250" text-anchor="end" font-size="11" fill="#60796b">{date(series.at(-1)!.measured_at)}</text></svg><details><summary>{t('uxChartData')}</summary><table><thead><tr><th>{t('measured_at')}</th><th>{t('value')}</th><th>{t('method')}</th></tr></thead><tbody>{#each series as a}<tr><td>{new Intl.DateTimeFormat(lang,{dateStyle:'short',timeStyle:'short',timeZone:timezone}).format(new Date(a.measured_at))}</td><td>{number(Number(a.value))} {a.unit}</td><td>{a.method}</td></tr>{/each}</tbody></table></details>{:else}<p class="empty-state">{t('uxEmptyHint')}</p>{/if}</section>
<style>.chart-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px}.chart-head h2{margin:0}.selectors{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:14px}.selectors label{font-size:11px}.selectors select{font-size:12px}.reading{display:flex;align-items:end;justify-content:space-between;margin-top:24px}.reading strong{font-size:27px;letter-spacing:-.6px}.reading small{font-size:13px;color:var(--muted);margin-left:8px;font-weight:400}.reading>span{color:var(--muted);font-size:11px}svg{width:100%;margin-top:15px;max-height:300px}summary{font-size:12px;color:var(--muted)}table{width:100%;font-size:12px;border-collapse:collapse;text-align:left}td,th{padding:9px;border-bottom:1px solid var(--line)}@media(max-width:700px){.selectors{grid-template-columns:1fr}.reading{align-items:flex-start;flex-direction:column;gap:6px}}
</style>
